frappe.listview_settings['Water Meter'] = {
    onload: function(listview) {
        listview.page.add_inner_button('Get Meter Data', function() {
            frappe.show_alert({message: 'Fetching water meter data...', indicator: 'blue'});
            frappe.call({
                method: "upande_hydrax.upande_hydrax.tasks.sync_all_water_meters",
                callback: function(r) {
                    frappe.show_alert({message: 'Water meter data updated', indicator: 'green'});
                    listview.refresh();
                },
                error: function(r) {
                    frappe.show_alert({message: 'Sync failed — check Error Log', indicator: 'red'});
                }
            });
        });
    }
};

