frappe.listview_settings['DCU'] = {
    onload: function(listview) {
        listview.page.add_inner_button('Get DCU Status', function() {
            frappe.show_alert({message: 'Fetching DCU status...', indicator: 'blue'});
            frappe.call({
                method: "upande_hydrax.upande_hydrax.tasks.sync_all_dcus",
                callback: function(r) {
                    frappe.show_alert({message: 'DCU status updated', indicator: 'green'});
                    listview.refresh();
                },
                error: function(r) {
                    frappe.show_alert({message: 'Sync failed — check Error Log', indicator: 'red'});
                }
            });
        });
    },
    get_indicator: function(doc) {
        if (doc.status === "Online") {
            return [__("Online"), "green", "status,=,Online"];
        } else {
            return [__("Offline"), "red", "status,=,Offline"];
        }
    },
    formatters: {
        status: function(value) {
            var is_online = value === "Online";
            var bg = is_online ? "#10b981" : "#ef4444";
            var knob_pos = is_online ? "18px" : "2px";
            return `
                <div style="display:flex; align-items:center; gap:6px;">
                    <div style="position:relative; width:34px; height:18px; background:${bg}; border-radius:20px; flex-shrink:0;">
                        <div style="position:absolute; top:2px; left:${knob_pos}; width:14px; height:14px; background:#fff; border-radius:50%; transition:left 0.15s;"></div>
                    </div>
                    <span style="font-size:12px; color:${bg}; font-weight:600;">${value}</span>
                </div>
            `;
        }
    }
};

